51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
101	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
102	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
111	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
112	        }
113	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
114	        if (!sharesHousehold && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        if (sharesHousehold) {
124	            owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getAddress()));
125	        }
126	        this.clinicService.saveOwner(owner);
127	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
128	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
129	            ownerMapper.formatMembershipLevel(owner));
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
